// Use only the customer's request, never French/English form labels or contact fields.
function requestLanguage(text) {
 const words=new Set(String(text||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().match(/[a-z]+/g)||[]);
 const fr=['bonjour','merci','besoin','electricien','electrique','electriques','panneau','prises','travaux','devis','depannage','reparation','souhaite','voudrais','pouvez','borne','recharge','je','nous','vous','mon','ma','mes','pour'];
 const en=['hello','hi','thanks','please','need','electrician','electrical','outlet','outlets','panel','repair','quote','estimate','wiring','charger','could','would','help','i','my','we','our','your','home'];
 const score=list=>list.filter(w=>words.has(w)).length;
 const f=score(fr),e=score(en);
 return e>=2&&e>f?'en':f>=2&&f>e?'fr':'uncertain';
}

// IMAP simple format. Preserve complete text for the intent gate.
function header(value='') {
  return String(value).replace(/=\?([^?]+)\?([bq])\?([^?]*)\?=/gi,(_,cs,enc,body)=>{
    const bytes=enc.toLowerCase()==='b'?Buffer.from(body,'base64'):Buffer.from(body.replace(/_/g,' ').replace(/=([0-9a-f]{2})/gi,(_,h)=>String.fromCharCode(parseInt(h,16))),'latin1');
    return bytes.toString(/8859|latin/i.test(cs)?'latin1':'utf8');
  });
}
function addresses(value='') {
  const text=header(typeof value==='string'?value:value.text||'');
  return {text,value:(text.match(/[A-Z0-9.!#$%&'*+/=?^_{|}~-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi)||[]).map(address=>({address:address.toLowerCase(),name:''}))};
}
return $input.all().map((item,index)=>{
  const j=item.json,h=Object.fromEntries(Object.entries(j.metadata||{}).map(([k,v])=>[k.toLowerCase(),v]));
  const html=String(j.textHtml||'').replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi,'').replace(/<\/(p|div|li|tr|h[1-6])\s*>|<br\s*\/?>/gi,'\n').replace(/<[^>]*>/g,' ').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&quot;/gi,'"').replace(/&#39;/g,"'");
  const text=String(j.textPlain||html||'').replace(/\r\n?/g,'\n').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g,'').trim();
  if(text.length>500000)throw new Error('Message too large; inspect manually');
  const from=addresses(j.from||h.from),to=addresses(j.to||h.to),replyTo=addresses(h['reply-to']||'');
  const subject=header(j.subject||h.subject||''),date=String(j.date||h.date||''),rfcMessageId=String(h['message-id']||'');
  const mailbox='support@sonicproelectricite.ca';
  const websiteForm=['siteweb@sonicproelectricite.ca',mailbox].includes(from.value[0]?.address)&&/demande de contact|demande depuis le site sonic-pro|contact request/i.test(subject);
  // Extract only labelled form fields before Message; instructions inside the message cannot replace them.
  const labels='Nom(?: complet)?|Name|Full name|Courriel|E-?mail(?: address)?|Téléphone|Telephone|Phone(?: number)?|Num[eé]ro de t[eé]l[eé]phone|Adresse|Address|Message|Votre message|Your message';
  const matches=[...text.matchAll(new RegExp('(?<!\\S)('+labels+')[ \\t]*:[ \\t]*','gi'))],fields={},duplicates=[];
  for(let i=0;i<matches.length;i++){
    const label=matches[i][1].normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
    const key=/^(nom|name|full name)/.test(label)?'name':/courriel|e-?mail/.test(label)?'email':/telephone|phone/.test(label)?'phone':/adresse|address/.test(label)?'address':'message';
    const value=text.slice(matches[i].index+matches[i][0].length,key==='message'?text.length:matches[i+1]?.index??text.length).trim();
    if(Object.hasOwn(fields,key)&&fields[key]!==value)duplicates.push(key);else fields[key]=value;
    if(key==='message')break;
  }
  const customerEmail=websiteForm?String(fields.email||'').trim().toLowerCase():'';
  const recipient=String(customerEmail||replyTo.value[0]?.address||(!websiteForm?from.value[0]?.address:'')||'').trim().toLowerCase();
  const safeRecipient=/^[A-Z0-9.!#$%&'*+/=?^_{|}~-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i.test(recipient)&&!/[\r\n,;]/.test(recipient)&&!['support@sonicproelectricite.ca','siteweb@sonicproelectricite.ca'].includes(recipient)&&!/^(?:mailer-daemon|postmaster|no-?reply)@/i.test(recipient);
  const automatic=!!(h['auto-submitted']&&String(h['auto-submitted']).toLowerCase()!=='no'&&(!websiteForm||String(h['auto-submitted']).toLowerCase()==='auto-replied'))||/bulk|list|junk/i.test(String(h.precedence||''))||!!h['list-id']||/^(?:mailer-daemon|postmaster|no-?reply)@/i.test(from.value[0]?.address||'')||(!websiteForm&&from.value.some(a=>/^(?:calendar-notification|calendar)@google\.com$/.test(a.address)))||(from.value[0]?.address===mailbox&&!websiteForm);
